const updateEvent = `-- name: UpdateEvent :execrows
UPDATE events
SET tag            = $1,
    internal_name  = $2,
    available_from = $3::timestamptz,
    archive_at     = $4::timestamptz,
    updated_at     = $5,
    updated_by     = $6,
    -- Until moderators configure the lifecycle, keep internal placeholders
    -- aligned with the platform window. They are never public dates.
    publish_at     = CASE WHEN NOT lifecycle_configured
                          THEN $3::timestamptz ELSE publish_at END,
    start_at       = CASE WHEN NOT lifecycle_configured
                          THEN $3::timestamptz ELSE start_at END
WHERE id = $7
  -- Optimistic lock: 0 rows means "modified since read" (or gone).
  AND updated_at IS NOT DISTINCT FROM $8
`

type UpdateEventParams struct {
	Tag               string             `json:"tag"`
	InternalName      string             `json:"internal_name"`
	AvailableFrom     time.Time          `json:"available_from"`
	ArchiveAt         pgtype.Timestamptz `json:"archive_at"`
	UpdatedAt         pgtype.Timestamptz `json:"updated_at"`
	UpdatedBy         uuid.NullUUID      `json:"updated_by"`
	ID                uuid.UUID          `json:"id"`
	ExpectedUpdatedAt pgtype.Timestamptz `json:"expected_updated_at"`
}

// Whole-aggregate write; excludes created_at/created_by (immutable).
func (q *Queries) UpdateEvent(ctx context.Context, arg UpdateEventParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateEvent,
		arg.Tag,
		arg.InternalName,
		arg.AvailableFrom,
		arg.ArchiveAt,
		arg.UpdatedAt,
		arg.UpdatedBy,
		arg.ID,
		arg.ExpectedUpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

